                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
    }

    @Test
    void modalidadeInexistenteRetornaModalidadeInvalida() throws Exception {
        String corpo = """
                {
                  "itens": %s,
